parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "score_ai_orchestration": { 
      "type": "number",
      "description": "Rate 1-5 the prominence of coding internal agent state logic, multi-step loops, and execution graphs. Set to a maximum of 2 if the role only builds external security proxy gateways, firewalls, or hosting infrastructure around agents. Default to 1 if it is a traditional data or analytics role."
    },
    "score_ai_mentoring": { 
      "type": "number",
      "description": "Rate 1-5 the prominence of coaching human teams, prompt engineering workshops, and AI change management. Set to 1 if unmentioned."
    },
    "score_ai_strategy": { 
      "type": "number",
      "description": "Rate 1-5 the prominence of executive AI roadmaps or monetization strategy. Strictly set to 1 if stakeholder interaction is simply gathering metrics, operational requirements, or business logic for standard database tables, data warehouses, or reporting dashboards."
    },
    "score_ai_infrastructure": { 
      "type": "number",
      "description": "Rate 1-5 the prominence of high-level AI platform engineering, proxy gateways, token trackers, security firewalls, or container runtimes. Set to 1 if the role is traditional data warehousing (Snowflake, dbt) OR if it involves low-level ML optimization like model quantization, distillation, or CUDA tuning."
},
    "experience_lower_bounds": {
      "type": "array",
      "items": { "type": "number" },
      "description": "List of all minimum/lower-bound years of professional employment experience explicitly required. If no years are mentioned at all, return exactly [0]."
    }
  },
  "required": [
    "score_ai_orchestration",
    "score_ai_mentoring",
    "score_ai_strategy",
    "score_ai_infrastructure",
    "experience_lower_bounds"
  ]
}

parameters.jsCode:
const rawCosine = $json.ideal_score_cosine;

const min = 0.53;
const max = 0.67;

let adjustedCosine = (rawCosine - min) / (max - min);

adjustedCosine = Math.max(0, Math.min(1, adjustedCosine));

const multipliedCosine = Math.round(adjustedCosine * 100);

return  {
    ideal_score_cosine: adjustedCosine,
    multipliedCosine
  }
;

const item = $json;

const rawWorkload = item.total_ai_workload_score || 4;
const normalizedResponsibility = (rawWorkload - 4) / 16;

const responsibilityWeighted = normalizedResponsibility * 0.85;
const idealCosineWeighted = (item.ideal_score_cosine || 0) * 0.15;
const finalWeightedScore = responsibilityWeighted + idealCosineWeighted;

return {
  final_weighted_score: Number(finalWeightedScore.toFixed(2)),
  responsibility_weighted: Number(responsibilityWeighted.toFixed(2)),
  ideal_cosine_weighted: Number(idealCosineWeighted.toFixed(2))
};

const data = $json.output; 

// Calculate the total AI Workload score across all 4 domains
const sumScore = data.score_ai_orchestration + 
                 data.score_ai_mentoring + 
                 data.score_ai_strategy + 
                 data.score_ai_infrastructure;

// Find the highest lower bound experience number
const lowerBounds = data.experience_lower_bounds || [0];
const maxRequiredExperience = Math.max(...lowerBounds);

return {
  total_ai_workload_score: sumScore,
  max_experience_detected: maxRequiredExperience,
};

const item = $json;
const weightedScore = item.final_weighted_score || 0;
const multipliedScore = Math.round(weightedScore * 100);

// Referencing the Merge node for seniority data
const maxExperience = $('Merge').item.json.max_experience_detected || 0;

const passMin = 0.27;
let finalDecision = 'passed';
let applicationStage = 'lead';

if (maxExperience >= 5) {
  finalDecision = 'rejected_seniority';
  applicationStage = 'withdrawn';
} else if (weightedScore < passMin) {
  finalDecision = 'rejected_responsibility';
  applicationStage = 'withdrawn';
}

return {
  final_weighted_score: weightedScore,
  responsibility_weighted: item.responsibility_weighted || 0,
  ideal_cosine_weighted: item.ideal_cosine_weighted || 0,
  max_experience_detected: maxExperience,
  multipliedScore: multipliedScore,
  status: finalDecision,
  applicationStage: applicationStage
};

